"use strict";(self.webpackChunkpf_1_ee=self.webpackChunkpf_1_ee||[]).push([[1283],{4914:(e,r,a)=>{a.r(r),a.d(r,{assets:()=>h,contentTitle:()=>o,default:()=>c,frontMatter:()=>i,metadata:()=>n,toc:()=>l});const n=JSON.parse('{"id":"srd/races/versatile-lineages/dhampirs","title":"Dhampirs","description":"Dhampirs are the haunted children of the living and the undead\u2014born of mortal mothers and vampire fathers. Their existence straddles two worlds: one beating with fragile warmth, the other cloaked in the cold stillness of undeath. Whether conceived through dark seduction, predatory violence, or arcane corruption, dhampirs are creatures of sorrow and contradiction. Most are unwanted. Few are understood.","source":"@site/docs/srd/races/versatile-lineages/dhampirs.md","sourceDirName":"srd/races/versatile-lineages","slug":"/srd/races/versatile-lineages/dhampirs","permalink":"/PF1EE/docs/srd/races/versatile-lineages/dhampirs","draft":false,"unlisted":false,"editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/docs/srd/races/versatile-lineages/dhampirs.md","tags":[],"version":"current","frontMatter":{},"sidebar":"srdSidebar","previous":{"title":"Changelings","permalink":"/PF1EE/docs/srd/races/versatile-lineages/changelings"},"next":{"title":"Skinwalkers","permalink":"/PF1EE/docs/srd/races/versatile-lineages/skinwalkers"}}');var t=a(4848),s=a(8453);const i={},o="Dhampirs",h={},l=[{value:"Dhampir Details",id:"dhampir-details",level:2},{value:"Dhampir Lineages",id:"dhampir-lineages",level:2},{value:"Graveborn Lineage Traits",id:"graveborn-lineage-traits",level:3}];function d(e){const r={em:"em",h1:"h1",h2:"h2",h3:"h3",header:"header",hr:"hr",li:"li",p:"p",strong:"strong",ul:"ul",...(0,s.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(r.header,{children:(0,t.jsx)(r.h1,{id:"dhampirs",children:"Dhampirs"})}),"\n",(0,t.jsx)(r.p,{children:"Dhampirs are the haunted children of the living and the undead\u2014born of mortal mothers and vampire fathers. Their existence straddles two worlds: one beating with fragile warmth, the other cloaked in the cold stillness of undeath. Whether conceived through dark seduction, predatory violence, or arcane corruption, dhampirs are creatures of sorrow and contradiction. Most are unwanted. Few are understood."}),"\n",(0,t.jsx)(r.p,{children:"Tales whisper that a dhampir is born not only from blood, but from tragedy\u2014that the very act of their birth drains the vitality from their mother. Many do not survive. Those that do often abandon their pale, fanged children in fear or horror, leaving them to grow in orphanages, monasteries, or the shadows of forgotten places."}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.strong,{children:"Bloodbound Dissonance:"})," From the moment they draw breath, dhampirs carry a burden no mortal child can comprehend. Their undead heritage makes them immune to the passage of time in ways that baffle even elves, yet they remain undeniably mortal\u2014capable of dying, loving, bleeding. They cast reflections and draw breath, yet flinch from sunlight and recoil at the presence of holy symbols. This duality gnaws at them. Many feel a hollow longing they cannot name\u2014a yearning for something that neither life nor death can satisfy."]}),"\n",(0,t.jsx)(r.p,{children:"As they mature, dhampirs become more aware of their unnatural nature. Their hearts beat slower. Their wounds knit faster. They hunger\u2014not for sustenance, but for something more primal: power, vengeance, blood. Most suppress it. Some indulge it. A rare few seek to master it."}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.strong,{children:"Living Shadows:"})," A dhampir\u2019s presence is magnetic and unsettling. Slender and statuesque, they move with a grace that seems rehearsed by instinct, not training. Their eyes glint in dim light, and their voices often carry a melodious lilt that can charm or unnerve. Skin tones range from ghastly pale to bruised violet, and their elongated canines\u2014though not true fangs\u2014hint at a hunger best left unspoken."]}),"\n",(0,t.jsx)(r.p,{children:"Some dhampirs can pass for human at a glance, but the illusion never lasts long. There is always something uncanny in their gaze or manner\u2014something that makes strangers clutch charms, cross thresholds, or lock doors a little sooner."}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.strong,{children:"The Curse of Memory:"})," Dhampirs are born to no culture and raised in none of their own. They learn to adapt quickly, to survive on wit and charm, or else on steel and shadow. Many find solace in old ruins, forgotten libraries, or the edge of civilization\u2014where questions are few and secrets are currency."]}),"\n",(0,t.jsx)(r.p,{children:"Still, the past haunts them. Whether it is a mother\u2019s silence, a village\u2019s cruelty, or the memory of fangs in the dark, a dhampir often walks with ghosts. Some are literal. Others are not."}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.strong,{children:"Bloodlines and Burdens:"})," Not all dhampirs are the same. Some inherit the cold elegance of nosferatu, others the cruel charm of moroi. Some radiate death like a fog, while others drain warmth from the air itself. These traits often emerge unpredictably, especially in places soaked in sorrow, near graveyards, or during the long hours before dawn."]}),"\n",(0,t.jsx)(r.p,{children:"Though most dhampirs are sterile, their lineage still echoes forward\u2014many of their children, if born at all, are marked by strange magic, cursed fates, or the undead bloodline in sorcery."}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.strong,{children:"Loners and Wanderers:"})," Dhampirs rarely gather. When they do, it is in secret\u2014cults, cabals, or desperate alliances forged not out of kinship but necessity. Most choose solitude, fearing that their curse may one day turn inward or lash out at those they care for. Others become hunters, seeking out the undead as if in vengeance for their own nature."]}),"\n",(0,t.jsx)(r.p,{children:"Their path is often that of the rogue, the inquisitor, or the necromancer\u2014professions where knowledge of death becomes a weapon and survival is the first commandment."}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.strong,{children:"Monsters or Martyrs:"})," For every dhampir who succumbs to the darkness within, another rises to defy it. They are champions of the night, slayers of their own kind, or caretakers of graveyards. But even the most virtuous dhampir walks with a shadow at their side, and no act of heroism can fully cleanse the stain of their origin."]}),"\n",(0,t.jsx)(r.p,{children:"They are creatures of contrast\u2014living shadows who haunt the borders between light and dark, life and death, hope and despair."}),"\n",(0,t.jsx)(r.hr,{}),"\n",(0,t.jsx)(r.h2,{id:"dhampir-details",children:"Dhampir Details"}),"\n",(0,t.jsx)(r.p,{children:"To play a character with a Dhampir lineage, first select your race, just like you would for any character. You gain hit points, type, size, speed, languages, lineage traits, and other abilities from that race. Then, instead of choosing a lineage from those normally available to that race, apply your chosen Dhampir lineage. You gain all the features from your Dhampir lineage, some of which might modify or replace statistics, abilities, or traits from your race."}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.strong,{children:"When you apply a Dhampir lineage, you gain the Dhampir subtype,"})," while retaining any racial subtypes, creature size, and racial traits associated with your base race (e.g., Dwarf, Elf, Human)."]}),"\n",(0,t.jsx)(r.p,{children:"Since a Dhampir lineage is a lineage, you can only apply one, and you cannot take another lineage in addition to your Dhampir lineage."}),"\n",(0,t.jsx)(r.p,{children:"When selecting lineage traits, you can choose from those available to your race as well as those available to your Dhampir lineage."}),"\n",(0,t.jsx)(r.hr,{}),"\n",(0,t.jsx)(r.h2,{id:"dhampir-lineages",children:"Dhampir Lineages"}),"\n",(0,t.jsx)(r.h3,{id:"graveborn-lineage-traits",children:"Graveborn Lineage Traits"}),"\n",(0,t.jsx)(r.p,{children:"Graveborn are dhampirs\u2014creatures born of mortal blood and undead sin. Caught between life and death, they inherit a paradox of existence: breathing, yet touched by the grave. Whether the result of a vampire\u2019s cursed bite upon an unborn child or a darker union best left unspoken, Graveborn walk the world with beauty that chills and a soul forever shadowed."}),"\n",(0,t.jsxs)(r.ul,{children:["\n",(0,t.jsxs)(r.li,{children:["\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.strong,{children:"Cursed Grace:"})," Graveborn possess a haunting beauty and unnatural agility. They gain +2 Dexterity**, +2 Charisma, \u20132 Constitution, and a +2 bonus to one other ability score of their choice, except Dexterity or Charisma."]}),"\n"]}),"\n",(0,t.jsxs)(r.li,{children:["\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.strong,{children:"Blood Without Decay:"})," Death does not claim a Graveborn easily. They take no penalties from energy drain effects, though they can still be killed if they accrue more negative levels than they have Hit Dice. After 24 hours, any negative levels they possess are removed automatically without requiring a saving throw."]}),"\n"]}),"\n",(0,t.jsxs)(r.li,{children:["\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.strong,{children:"Graveborn Fortitude:"})," The taint of undeath grants strange resilience. Graveborn gain a +2 racial bonus on saving throws against disease and mind-affecting effects."]}),"\n"]}),"\n",(0,t.jsxs)(r.li,{children:["\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.strong,{children:"Negative Energy Affinity:"})," Though living, a Graveborn reacts to energy as if undead\u2014positive energy harms them, while negative energy heals them."]}),"\n"]}),"\n",(0,t.jsxs)(r.li,{children:["\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.strong,{children:"Predatory Nature:"})," A lifetime spent navigating fear, suspicion, and lies hones the Graveborn\u2019s instincts. They gain a +2 racial bonus on Bluff and Perception checks."]}),"\n"]}),"\n",(0,t.jsxs)(r.li,{children:["\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.strong,{children:"Whispers from the Grave:"})," Graveborn can cast ",(0,t.jsx)(r.em,{children:"detect undead"})," once per day as a spell-like ability. They often describe this as a chilling awareness of death lingering nearby. The caster level equals the Graveborn\u2019s character level."]}),"\n"]}),"\n",(0,t.jsxs)(r.li,{children:["\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.strong,{children:"Vampiric Eyes:"})," A Graveborn\u2019s gaze pierces gloom like moonlight over headstones. They can see twice as far as humans in dim light, gaining low-light vision. If they already possess low-light vision from their base race, they instead gain darkvision out to 60 feet."]}),"\n"]}),"\n"]})]})}function c(e={}){const{wrapper:r}={...(0,s.R)(),...e.components};return r?(0,t.jsx)(r,{...e,children:(0,t.jsx)(d,{...e})}):d(e)}},8453:(e,r,a)=>{a.d(r,{R:()=>i,x:()=>o});var n=a(6540);const t={},s=n.createContext(t);function i(e){const r=n.useContext(s);return n.useMemo((function(){return"function"==typeof e?e(r):{...r,...e}}),[r,e])}function o(e){let r;return r=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:i(e.components),n.createElement(s.Provider,{value:r},e.children)}}}]);